def build_child_chunk(section, child_text, chunk_id, parent_id):
    """生成用于检索的子块：拼接标题路径作为向量化上下文，
    但父级正文只存仓库不建索引"""
    heading_path = " > ".join(section["heading_chain"])  # 如 第三章>3.2节
    embed_text = f"{heading_path}\n{child_text}"  # 仅用于计算 embedding
    return {
        "chunk_id": chunk_id,
        "parent_id": parent_id,          # 指向父块，检索命中后回填用
        "embed_text": embed_text,        # 送入 embedding 模型
        "display_text": child_text,      # 真正展示/回填时用的原文
    }

def resolve_context(hit_chunk_ids, parent_store):
    """命中子块后，去重回填父块内容，避免同一父块重复出现"""
    parent_ids = []
    for cid in hit_chunk_ids:
        pid = chunk_store[cid]["parent_id"]
        if pid not in parent_ids:
            parent_ids.append(pid)
    return [parent_store[pid] for pid in parent_ids]

def rrf_fuse(rank_lists, k=60):
    """rank_lists: 多路召回结果，每个元素是按名次排好的 doc_id 列表
    返回融合后按分数降序排列的 doc_id 列表"""
    scores = {}
    for ranked_docs in rank_lists:
        for rank, doc_id in enumerate(ranked_docs, start=1):
            scores[doc_id] = scores.get(doc_id, 0.0) + 1.0 / (k + rank)
    return sorted(scores, key=lambda d: scores[d], reverse=True)

