# 增量索引核心逻辑：基于内容哈希识别变更
import hashlib

def content_hash(text: str) -> str:
    return hashlib.sha256(text.encode("utf-8")).hexdigest()

def diff_chunks(old_manifest: dict, new_chunks: list) -> dict:
    # old_manifest: {chunk_id: content_hash}
    new_manifest = {c["chunk_id"]: content_hash(c["text"]) for c in new_chunks}
    added = [cid for cid in new_manifest if cid not in old_manifest]
    deleted = [cid for cid in old_manifest if cid not in new_manifest]
    modified = [
        cid for cid in new_manifest
        if cid in old_manifest and old_manifest[cid] != new_manifest[cid]
    ]
    return {"added": added, "modified": modified, "deleted": deleted}

def sync_index(vector_store, diff, new_chunks_by_id):
    # 修改 = 先软删旧向量，再插入新向量，最后物理清理
    for cid in diff["modified"] + diff["deleted"]:
        vector_store.mark_deleted(cid)
    for cid in diff["added"] + diff["modified"]:
        chunk = new_chunks_by_id[cid]
        vector_store.upsert(cid, embed(chunk["text"]), chunk["metadata"])
    vector_store.purge_soft_deleted(older_than="1h")

